MOD = 998244353

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """
    Count the number of ways to replace '?' with '1','2','3' so that
    adjacent cells have different digits.  Grid size satisfies H*W ≤ 200.
    """
    from collections import deque

    # Convert grid to list of ints, -1 for '?'
    g = [[-1] * W for _ in range(H)]
    for i in range(H):
        for j, ch in enumerate(grid[i]):
            if ch != '?':
                g[i][j] = int(ch) - 1          # use 0..2 internally

    visited = [[False] * W for _ in range(H)]
    ans = 1

    # directions
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for si in range(H):
        for sj in range(W):
            if visited[si][sj]:
                continue
            # start new component
            q = deque()
            q.append((si, sj))
            visited[si][sj] = True
            parity = {}
            parity[(si, sj)] = 0

            # forced colors for each parity, -1 means not forced yet
            forced = [-1, -1]          # index 0 -> parity 0, 1 -> parity 1
            has_par = [False, False]  # whether this parity actually appears

            while q:
                i, j = q.popleft()
                p = parity[(i, j)]
                has_par[p] = True
                if g[i][j] != -1:          # pre‑colored
                    if forced[p] == -1:
                        forced[p] = g[i][j]
                    elif forced[p] != g[i][j]:
                        # conflict inside same parity -> impossible
                        return 0

                for di, dj in dirs:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W:
                        if not visited[ni][nj]:
                            visited[ni][nj] = True
                            parity[(ni, nj)] = p ^ 1
                            q.append((ni, nj))
                        else:
                            # already visited: check bipartite parity consistency
                            if parity[(ni, nj)] == p:
                                # odd cycle -> not bipartite, impossible with 3 colors
                                return 0

            # count valid assignments for this component
            if not has_par[1]:          # only one parity present (isolated vertex)
                if forced[0] == -1:
                    ways = 3
                else:
                    ways = 1
            else:
                ways = 0
                for c0 in range(3):
                    if forced[0] != -1 and c0 != forced[0]:
                        continue
                    for c1 in range(3):
                        if c0 == c1:
                            continue
                        if forced[1] != -1 and c1 != forced[1]:
                            continue
                        ways += 1
                # ways is at most 6
            ans = (ans * ways) % MOD

    return ans
